import {today, uid, cents, money, addDays, addMonths, monthStart, monthEnd, weekStart, periodRange, inRange, actual, sum, metrics, nextDue, groupSum, toCsv, parseCsv, dateObj, FREQUENCIES} from './finance.js?v=2';
import {freshState, loadState, saveState, validateBackup, writeThrough} from './storage.js?v=2';

const root = document.querySelector('#app');
let state = freshState();
let page = 'dashboard', period = 'month', anchor = today(), custom = {from:monthStart(today()),to:today()};
let search = '', filterType = 'All', filterCategory = 'All', filterStatus = 'All', sortBy = 'date', sortDir = -1;
let selectedWeek = weekStart(today()), selectedMonth = monthStart(today()), selectedDate = today();
let modal = null, toastTimer, pendingSave = Promise.resolve(), undoStack = [], mobileNav = false;
const nav = [['dashboard','Dashboard','grid'],['transactions','Transactions','table'],['weekly','Weekly Budget','calendar'],['monthly','Monthly Budget','calendar'],['bills','Bills','receipt'],['goals','Savings Goals','target'],['analytics','Analytics','chart'],['settings','Settings','settings']];
const iconPaths = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  table:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M3 15h18M9 3v18"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
  receipt:'<path d="M4 3h16v18l-4-2-4 2-4-2-4 2V3Z"/><path d="M8 8h8M8 12h8"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  chart:'<path d="M3 3v18h18M7 16l4-5 4 2 5-7"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .34 1.88l.07.07-2.86 2.86-.07-.07A1.7 1.7 0 0 0 15 19.4a1.7 1.7 0 0 0-1.2 1.6V21h-4v-.1A1.7 1.7 0 0 0 8.6 19.4a1.7 1.7 0 0 0-1.88.34l-.07.07-2.86-2.86.07-.07A1.7 1.7 0 0 0 4.2 15a1.7 1.7 0 0 0-1.6-1.2H2.5v-4h.1A1.7 1.7 0 0 0 4.2 8.6a1.7 1.7 0 0 0-.34-1.88l-.07-.07 2.86-2.86.07.07A1.7 1.7 0 0 0 8.6 4.2a1.7 1.7 0 0 0 1.2-1.6V2.5h4v.1A1.7 1.7 0 0 0 15 4.2a1.7 1.7 0 0 0 1.88-.34l.07-.07 2.86 2.86-.07.07A1.7 1.7 0 0 0 19.4 8.6a1.7 1.7 0 0 0 1.6 1.2h.1v4H21a1.7 1.7 0 0 0-1.6 1.2Z"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>', chevron:'<path d="m9 18 6-6-6-6"/>', down:'<path d="m6 9 6 6 6-6"/>', download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>', upload:'<path d="M12 21V9m-4 4 4-4 4 4M4 7V3h16v4"/>', more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>', undo:'<path d="M9 14 4 9l5-5M4 9h10a6 6 0 0 1 0 12h-2"/>', x:'<path d="M18 6 6 18M6 6l12 12"/>', menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 15h2"/>', spark:'<path d="m12 2 1.8 6.2L20 10l-6.2 1.8L12 18l-1.8-6.2L4 10l6.2-1.8L12 2ZM19 18l.6 1.4L21 20l-1.4.6L19 22l-.6-1.4L17 20l1.4-.6L19 18Z"/>'
};
const icon = (name,size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.grid}</svg>`;
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => money(n,state.settings.currency);
const niceDate = s => s ? dateObj(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : '—';
const shortDate = s => s ? dateObj(s).toLocaleDateString(undefined,{month:'short',day:'numeric'}) : '—';
const monthLabel = s => dateObj(s).toLocaleDateString(undefined,{month:'long',year:'numeric'});
const statusOptions = type => type === 'Income' ? ['Received','Expected'] : type === 'Expense' ? ['Paid','Upcoming'] : ['Cleared','Planned'];
const option = (value,label,selected) => `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;
const catOptions = selected => state.categories.map(c=>option(c,c,selected)).join('');
const typeOptions = selected => ['Income','Expense','Transfer','Savings'].map(t=>option(t,t,selected)).join('');
const select = (name,items,selected,extra='') => `<select name="${name}" ${extra}>${items.map(x=>option(x,x,selected)).join('')}</select>`;
const button = (label,action,variant='secondary',extra='') => `<button type="button" class="btn btn-${variant}" data-action="${action}" ${extra}>${label}</button>`;
const empty = (title,copy,action,label) => `<div class="empty">${icon('spark',28)}<h3>${title}</h3><p>${copy}</p>${action?button(label,action,'primary'):''}</div>`;
const card = (label,value,iconName,tone='') => `<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${tone}">${icon(iconName,17)}</span></div><strong>${value}</strong></div>`;
const titleRow = (eyebrow,title,description,actions='') => `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;
const tabPeriod = () => `<div class="period-controls"><div class="segmented">${[['week','Week'],['month','Month'],['year','Year'],['custom','Custom']].map(([v,l])=>`<button type="button" class="${period===v?'active':''}" data-action="period" data-value="${v}">${l}</button>`).join('')}</div>${period==='custom'?`<input type="date" data-custom="from" value="${custom.from}"><span>to</span><input type="date" data-custom="to" value="${custom.to}">`:`<div class="date-step">${button('‹','prev-period')}<span>${period==='week'?`${shortDate(periodRange(period,anchor,custom,state.settings.weekStarts).from)} – ${shortDate(periodRange(period,anchor,custom,state.settings.weekStarts).to)}`:period==='year'?anchor.slice(0,4):monthLabel(anchor)}</span>${button('›','next-period')}</div>`}</div>`;
const txValue = (t,col) => col==='amountCents' ? (t.amountCents/100).toFixed(2) : t[col] ?? '';

function notify(message,bad=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className=`toast ${bad?'toast-bad':''}`;el.setAttribute('role','status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500);}
async function persist(){const snapshot=structuredClone(state);try{writeThrough(snapshot);}catch(e){notify(`Local backup could not be saved: ${e.message}`,true);}pendingSave=pendingSave.catch(()=>{}).then(()=>saveState(snapshot));try{await pendingSave;}catch(e){notify(`Could not save: ${e.message}`,true);}}
function remember(){undoStack.push(structuredClone(state));if(undoStack.length>30)undoStack.shift();}
function changed(message){persist();render();if(message)notify(message);}
function undo(){if(!undoStack.length)return notify('Nothing to undo.');state=undoStack.pop();changed('Change undone.');}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function currentRange(){return periodRange(period,anchor,custom,state.settings.weekStarts);}
function billOccurrences(range){let occurrences=[];for(const bill of state.bills){let d=bill.nextDue,n=0;while(d<=range.to&&n<500){if(d>=range.from)occurrences.push({...bill,due:d});const next=nextDue(d,bill.frequency);if(next<=d)break;d=next;n++;}}return occurrences.sort((a,b)=>a.due.localeCompare(b.due));}
function upcomingBills(range){return billOccurrences(range).filter(b=>!b.lastPaidDate || b.due>b.lastPaidDate);}
function goalSaved(goal){return sum(goal.movements,m=>m.amountCents);}
function allocationsFor(week){return state.allocations[week] || {};}
function estimatedPay(){const incomes=state.transactions.filter(t=>t.type==='Income'&&actual(t)&&t.date>=addDays(today(),-84));const weeks=new Set(incomes.map(t=>weekStart(t.date,state.settings.weekStarts)));return weeks.size?Math.round(sum(incomes)/weeks.size):0;}
function render(){const active=nav.find(x=>x[0]===page) || nav[0];root.innerHTML=`<div class="shell"><aside class="sidebar ${mobileNav?'open':''}"><div class="brand"><span class="brand-mark">N</span><span>northstar<span class="brand-dot">.</span><small>PERSONAL FINANCE</small></span></div><div class="workspace-label">WORKSPACE</div><nav aria-label="Main navigation">${nav.map(([id,label,ico])=>`<button type="button" class="nav-item ${page===id?'active':''}" data-page="${id}">${icon(ico)}<span>${label}</span>${page===id?'<span class="nav-indicator"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="privacy-note">${icon('wallet',18)}<span>Your data stays in<br>this browser.</span></div><div class="sidebar-footer">NORTHSTAR <span>v1.0</span></div></div></aside>${mobileNav?'<button class="mobile-scrim" data-action="toggle-nav" aria-label="Close menu"></button>':''}<div class="main-wrap"><header class="topbar"><div class="top-left"><button class="mobile-menu icon-button" data-action="toggle-nav" aria-label="Open menu">${icon('menu')}</button><span class="breadcrumb">Workspace</span>${icon('chevron',14)}<strong>${active[1]}</strong></div><div class="top-actions"><button class="global-search" data-action="global-search">${icon('search',16)}<span>Search transactions</span><kbd>Ctrl K</kbd></button><span class="top-divider"></span>${button(`${icon('plus',16)}<span>Quick add</span>`,'quick-add','primary')}</div></header><main class="main-content">${renderPage()}</main></div></div>${modal?renderModal():''}`;}
function renderPage(){switch(page){case 'transactions':return transactionsPage();case 'weekly':return weeklyPage();case 'monthly':return monthlyPage();case 'bills':return billsPage();case 'goals':return goalsPage();case 'analytics':return analyticsPage();case 'settings':return settingsPage();default:return dashboardPage();}}

function dashboardPage(){const range=currentRange(),m=metrics(state.transactions,range,state.settings.startingBalanceCents),upcoming=upcomingBills(range),billTotal=sum(upcoming,b=>b.amountCents),available=m.remaining-billTotal;
  const prev=period==='week'?{from:addDays(range.from,-7),to:addDays(range.to,-7)}:period==='year'?{from:addMonths(range.from,-12),to:addMonths(range.to,-12)}:{from:monthStart(addDays(range.from,-1)),to:addDays(range.from,-1)};
  const pm=metrics(state.transactions,prev),diff=m.expenses-pm.expenses;
  const expenses=m.rows.filter(t=>t.type==='Expense'),byCategory=Object.entries(groupSum(expenses,t=>t.category)).sort((a,b)=>b[1]-a[1]);
  const weeklyGroups=Array.from({length:7},(_,i)=>{const d=addDays(range.from,Math.floor((dateObj(range.to)-dateObj(range.from))/86400000*i/6));return {label:shortDate(d),income:sum(m.rows.filter(t=>t.type==='Income'&&t.date<=d)),expense:sum(expenses.filter(t=>t.date<=d))};});
  return `${titleRow('OVERVIEW','Good to see you.','Your money, in focus. Every figure comes from your entries.',button(`${icon('plus',16)} Add transaction`,'new-transaction','primary'))}${tabPeriod()}<div class="stats-grid">${card('Total income',fmt(m.income),'arrow','green')}${card('Total expenses',fmt(m.expenses),'wallet','rose')}${card('Money remaining',fmt(m.remaining),'wallet','blue')}${card('Savings moved',fmt(m.savings),'target','violet')}${card('Upcoming bills',fmt(billTotal),'receipt','amber')}${card('Available to spend',fmt(available),'spark','green')}</div><div class="dashboard-grid"><section class="panel span-2"><div class="panel-head"><div><h2>Cash flow</h2><p>Income and expenses through the selected period</p></div><span class="legend"><i class="dot green"></i> Income <i class="dot slate"></i> Expenses</span></div>${lineChart(weeklyGroups)}</section><section class="panel"><div class="panel-head"><div><h2>Spending by category</h2><p>Where your money went</p></div></div>${categoryBars(byCategory,m.expenses)}</section><section class="panel"><div class="panel-head"><div><h2>Financial pulse</h2><p>Useful context at a glance</p></div></div><div class="insights"><div><span>Spending vs. previous period</span><strong class="${diff>0?'negative':'positive'}">${pm.expenses?`${diff>0?'+':''}${Math.round(diff/pm.expenses*100)}%`:m.expenses?'New activity':'—'}</strong></div><div><span>Largest expense category</span><strong>${esc(byCategory[0]?.[0]||'—')}</strong></div><div><span>Current cash balance</span><strong>${fmt(m.balance)}</strong></div><div><span>Recorded transactions</span><strong>${m.rows.length}</strong></div></div></section><section class="panel span-2"><div class="panel-head"><div><h2>Recent activity</h2><p>Your latest confirmed entries</p></div><button class="text-button" data-page="transactions">View all ${icon('arrow',15)}</button></div>${recentRows(m.rows)}</section><section class="panel"><div class="panel-head"><div><h2>Coming due</h2><p>Bills in this period</p></div><button class="text-button" data-page="bills">Manage ${icon('arrow',15)}</button></div>${upcoming.length?upcoming.slice(0,5).map(b=>`<div class="mini-row"><span class="mini-icon">${icon('receipt',16)}</span><div><strong>${esc(b.name)}</strong><small>${shortDate(b.due)}</small></div><strong>${fmt(b.amountCents)}</strong></div>`).join(''):empty('All clear','No bills due in this period.','new-bill','Add bill')}</section></div>`;
}
function lineChart(data){const max=Math.max(100,...data.flatMap(x=>[x.income,x.expense]));const p=(key)=>data.map((x,i)=>`${36+i*86},${172-(x[key]/max)*138}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 600 210" role="img" aria-label="Cumulative income and expenses chart"><g class="chart-grid"><path d="M36 34H588M36 80H588M36 126H588M36 172H588"/></g><polyline points="${p('income')}" fill="none" stroke="#75d5ad" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${p('expense')}" fill="none" stroke="#8291a7" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${data.map((x,i)=>`<circle cx="${36+i*86}" cy="${172-x.income/max*138}" r="5" fill="#75d5ad"><title>${x.label}: income ${fmt(x.income)}</title></circle><circle cx="${36+i*86}" cy="${172-x.expense/max*138}" r="5" fill="#8291a7"><title>${x.label}: expenses ${fmt(x.expense)}</title></circle>`).join('')}</svg><div class="chart-labels">${data.map(x=>`<span>${x.label}</span>`).join('')}</div></div>`;}
function categoryBars(rows,total){return rows.length?`<div class="category-list">${rows.slice(0,6).map(([name,n],i)=>`<div class="category-row"><div><span class="category-dot dot-${i%6}"></span><span>${esc(name)}</span><strong>${fmt(n)}</strong></div><div class="bar-track"><div style="width:${Math.round(n/total*100)}%"></div></div></div>`).join('')}</div>`:empty('No spending yet','Expense categories appear here after you add a paid expense.');}
function recentRows(rows){const recent=[...rows].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return recent.length?`<div class="recent-list">${recent.map(t=>{const incoming=t.type==='Income'||(t.type==='Savings'&&t.direction==='in');return `<div class="recent-row"><span class="transaction-badge ${t.type.toLowerCase()}">${icon(incoming?'arrow':'wallet',16)}</span><div><strong>${esc(t.description)}</strong><small>${esc(t.category)} · ${shortDate(t.date)}</small></div><strong class="${incoming?'positive':''}">${incoming?'+':'−'}${fmt(t.amountCents)}</strong></div>`;}).join('')}</div>`:empty('Your canvas is ready','Add your first paycheck or expense to bring this dashboard to life.','new-transaction','Add first entry');}

const columns=[['date','Date'],['description','Description'],['category','Category'],['type','Type'],['amountCents','Amount'],['status','Status'],['notes','Notes']];
function filteredTransactions(){let rows=state.transactions.filter(t=>{const q=search.toLowerCase();return (!q||[t.description,t.category,t.notes,t.type].some(v=>String(v||'').toLowerCase().includes(q)))&&(filterType==='All'||t.type===filterType)&&(filterCategory==='All'||t.category===filterCategory)&&(filterStatus==='All'||t.status===filterStatus);});rows.sort((a,b)=>{const av=sortBy==='amountCents'?a.amountCents:String(a[sortBy]||'').toLowerCase(),bv=sortBy==='amountCents'?b.amountCents:String(b[sortBy]||'').toLowerCase();return av<bv?-sortDir:av>bv?sortDir:0;});return rows;}
function transactionsPage(){const rows=filteredTransactions(),income=sum(rows.filter(t=>t.type==='Income'&&actual(t))),expense=sum(rows.filter(t=>t.type==='Expense'&&actual(t)));
 return `${titleRow('YOUR LEDGER','Transactions','A flexible workspace for every paycheck, purchase, and transfer.',`${button(`${icon('upload',16)} Import CSV`,'import-csv')}${button(`${icon('download',16)} Export CSV`,'export-csv')}${button(`${icon('plus',16)} Add row`,'new-row','primary')}`)}<div class="toolbar"><label class="search-field">${icon('search',17)}<input id="transaction-search" type="search" placeholder="Search transactions…" value="${esc(search)}" aria-label="Search transactions"></label><select id="filter-type" aria-label="Filter type">${['All','Income','Expense','Transfer','Savings'].map(v=>option(v,v==='All'?'All types':v,filterType)).join('')}</select><select id="filter-category" aria-label="Filter category">${option('All','All categories',filterCategory)}${catOptions(filterCategory)}</select><select id="filter-status" aria-label="Filter status">${['All','Received','Expected','Paid','Upcoming','Cleared','Planned'].map(v=>option(v,v==='All'?'All statuses':v,filterStatus)).join('')}</select>${button(`${icon('undo',15)} Undo`,'undo','','title="Undo last edit"')}</div><div class="table-panel"><div class="table-scroll"><table class="ledger"><thead><tr>${columns.map(([key,label])=>`<th><button data-action="sort" data-value="${key}">${label}${sortBy===key?` <span>${sortDir===-1?'↓':'↑'}</span>`:''}</button></th>`).join('')}<th class="actions-cell">Actions</th></tr></thead><tbody>${rows.map(t=>transactionRow(t)).join('')}</tbody><tfoot><tr><td colspan="4">${rows.length} ${rows.length===1?'row':'rows'} · Confirmed totals</td><td class="num">${fmt(income-expense)}</td><td colspan="3"><span class="positive">+${fmt(income)}</span> <span class="muted">/</span> <span class="negative">−${fmt(expense)}</span></td></tr></tfoot></table>${!rows.length?empty(state.transactions.length?'No matches':'A clean slate',state.transactions.length?'Try changing your filters.':'Add a row to start tracking your money.','new-row','Add row'):''}</div></div><p class="table-help">Click any cell to edit. Tab and Shift+Tab move between cells. Paste a rectangular selection from a spreadsheet into a cell. Changes save automatically.</p>`;}
function transactionRow(t){return `<tr data-id="${t.id}" class="row-${t.type.toLowerCase()}">${columns.map(([key])=>`<td class="${key==='amountCents'?'num':''}">${key==='category'?`<select class="cell-select" data-cell="${key}" aria-label="Category for ${esc(t.description)}">${catOptions(t.category)}</select>`:key==='type'?`<select class="cell-select" data-cell="${key}" aria-label="Type for ${esc(t.description)}">${typeOptions(t.type)}</select>`:key==='status'?`<select class="cell-select status-${esc(t.status.toLowerCase())}" data-cell="${key}" aria-label="Status for ${esc(t.description)}">${statusOptions(t.type).map(v=>option(v,v,t.status)).join('')}</select>`:`<input class="cell-input ${key==='amountCents'?'amount-input':''}" data-cell="${key}" type="${key==='date'?'date':'text'}" value="${esc(txValue(t,key))}" aria-label="${key} for ${esc(t.description)}" ${key==='amountCents'?'inputmode="decimal"':''}>`}</td>`).join('')}<td class="actions-cell"><button class="row-action" data-action="duplicate-row" data-id="${t.id}" title="Duplicate row" aria-label="Duplicate row">${icon('plus',15)}</button><button class="row-action" data-action="delete-row" data-id="${t.id}" title="Delete row" aria-label="Delete row">${icon('x',15)}</button></td></tr>`;}

function weeklyPage(){const start=selectedWeek,end=addDays(start,6),range={from:start,to:end},m=metrics(state.transactions,range),bills=upcomingBills(range),planned=allocationsFor(start),plannedTotal=sum(Object.values(planned),x=>x),expected=estimatedPay(),forecastIncome=m.income || expected,forecastOut=plannedTotal+sum(bills,b=>b.amountCents);return `${titleRow('WEEKLY PLAN','Make this week count.','Plan your paycheck before it disappears into the details.',button(`${icon('plus',16)} Add allocation`,'new-allocation','primary'))}<div class="period-controls"><div class="date-step">${button('‹','prev-week')}<span>${shortDate(start)} – ${niceDate(end)}</span>${button('›','next-week')}</div><span class="muted">Week starts ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][state.settings.weekStarts]}</span></div><div class="stats-grid four">${card('Expected pay',fmt(expected),'arrow','green')}${card('Actual income',fmt(m.income),'wallet','blue')}${card('Planned outflow',fmt(forecastOut),'receipt','amber')}${card('Actual remaining',fmt(m.remaining),'target',m.remaining<0?'rose':'green')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Category allocations</h2><p>Planning does not change your cash balance</p></div></div>${Object.keys(planned).length?`<div class="allocation-list">${Object.entries(planned).map(([cat,amount])=>{const spent=sum(m.rows.filter(t=>t.type==='Expense'&&t.category===cat));return `<div class="allocation-row"><div><strong>${esc(cat)}</strong><small>${fmt(spent)} spent of ${fmt(amount)}</small></div><div class="allocation-progress"><div style="width:${Math.min(100,amount?spent/amount*100:0)}%"></div></div><button class="row-action" data-action="delete-allocation" data-value="${esc(cat)}" aria-label="Remove ${esc(cat)} allocation">${icon('x',15)}</button></div>`;}).join('')}</div>`:empty('No allocations yet','Give each category a plan for this week.','new-allocation','Add allocation')}<div class="panel-total"><span>Unallocated from expected pay</span><strong>${fmt(forecastIncome-forecastOut)}</strong></div></section><section class="panel"><div class="panel-head"><div><h2>This week</h2><p>Actual entries and obligations</p></div></div><div class="insights"><div><span>Expected remaining</span><strong>${fmt(forecastIncome-forecastOut)}</strong></div><div><span>Actual expenses</span><strong>${fmt(m.expenses)}</strong></div><div><span>Savings transfers</span><strong>${fmt(m.savings)}</strong></div><div><span>Over / under plan</span><strong class="${plannedTotal-m.expenses>=0?'positive':'negative'}">${fmt(plannedTotal-m.expenses)}</strong></div></div><h3 class="subheading">Bills due</h3>${bills.length?bills.map(b=>`<div class="mini-row"><span class="mini-icon">${icon('receipt',16)}</span><div><strong>${esc(b.name)}</strong><small>${shortDate(b.due)}</small></div><strong>${fmt(b.amountCents)}</strong></div>`).join(''):'<p class="muted compact">No bills due this week.</p>'}</section></div>`;}

function monthlyPage(){const start=selectedMonth,end=monthEnd(start),range={from:start,to:end},m=metrics(state.transactions,range),prev=metrics(state.transactions,{from:monthStart(addDays(start,-1)),to:addDays(start,-1)}),due=upcomingBills(range),expected=m.income+estimatedPay()*Math.max(0,Math.ceil((dateObj(end)-dateObj(today()))/604800000));const firstDay=dateObj(start).getDay(),days=dateObj(end).getDate();let cells=Array.from({length:firstDay},()=>'<div class="cal-empty"></div>');for(let d=1;d<=days;d++){const date=`${start.slice(0,8)}${String(d).padStart(2,'0')}`,items=state.transactions.filter(t=>t.date===date),bs=due.filter(b=>b.due===date);cells.push(`<button class="cal-day ${date===selectedDate?'selected':''} ${date===today()?'today':''}" data-action="select-date" data-value="${date}"><span>${d}</span>${items.slice(0,2).map(t=>`<small class="cal-event ${t.type.toLowerCase()}">${esc(t.description)}</small>`).join('')}${bs.slice(0,1).map(b=>`<small class="cal-event bill">${esc(b.name)}</small>`).join('')}${items.length+bs.length>3?`<small>+${items.length+bs.length-3} more</small>`:''}</button>`);}
const dayItems=state.transactions.filter(t=>t.date===selectedDate),dayBills=due.filter(b=>b.due===selectedDate);return `${titleRow('MONTHLY VIEW','The bigger picture.','Your calendar month, with every transaction on its actual date.',button(`${icon('plus',16)} Add entry`,'new-transaction','primary'))}<div class="period-controls"><div class="date-step">${button('‹','prev-month')}<span>${monthLabel(start)}</span>${button('›','next-month')}</div></div><div class="stats-grid four">${card('Income',fmt(m.income),'arrow','green')}${card('Expenses',fmt(m.expenses),'wallet','rose')}${card('Projected bills',fmt(sum(due,b=>b.amountCents)),'receipt','amber')}${card('Expected month end',fmt(expected-m.expenses-sum(due,b=>b.amountCents)),'target','blue')}</div><div class="two-col calendar-layout"><section class="panel calendar-panel"><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div></section><section class="panel day-panel"><div class="panel-head"><div><h2>${niceDate(selectedDate)}</h2><p>${dayItems.length} transaction${dayItems.length===1?'':'s'}</p></div><button class="row-action" data-action="add-on-date" title="Add transaction on this date">${icon('plus',18)}</button></div>${dayItems.length?recentRows(dayItems):'<p class="muted compact">No transactions on this day.</p>'}${dayBills.length?`<h3 class="subheading">Bills due</h3>${dayBills.map(b=>`<div class="mini-row"><strong>${esc(b.name)}</strong><strong>${fmt(b.amountCents)}</strong></div>`).join('')}`:''}<div class="divider"></div><div class="insights"><div><span>Previous month expenses</span><strong>${fmt(prev.expenses)}</strong></div><div><span>Change</span><strong class="${m.expenses-prev.expenses>0?'negative':'positive'}">${fmt(m.expenses-prev.expenses)}</strong></div></div></section></div>`;}

function billsPage(){const rows=[...state.bills].sort((a,b)=>a.nextDue.localeCompare(b.nextDue));return `${titleRow('RECURRING PAYMENTS','Stay ahead of bills.','Upcoming payments are forecasts until you record them as paid.',button(`${icon('plus',16)} Add bill`,'new-bill','primary'))}<div class="stats-grid three">${card('Active bills',String(rows.length),'receipt','blue')}${card('Due in 30 days',fmt(sum(upcomingBills({from:today(),to:addDays(today(),30)}),b=>b.amountCents)),'calendar','amber')}${card('Overdue',String(rows.filter(b=>b.nextDue<today()).length),'wallet','rose')}</div><section class="panel"><div class="panel-head"><div><h2>Your recurring bills</h2><p>Marking one paid creates a single expense transaction and advances its due date.</p></div></div>${rows.length?`<div class="bill-list">${rows.map(b=>`<div class="bill-row"><span class="bill-icon">${icon('receipt',19)}</span><div class="bill-name"><strong>${esc(b.name)}</strong><small>${esc(b.category)} · ${esc(b.frequency)} ${b.notes?`· ${esc(b.notes)}`:''}</small></div><div class="bill-due"><small>Next due</small><strong class="${b.nextDue<today()?'negative':''}">${shortDate(b.nextDue)}</strong></div><strong class="bill-amount">${fmt(b.amountCents)}</strong><div class="bill-actions">${button('Record paid','pay-bill','secondary',`data-id="${b.id}"`)}<button class="row-action" data-action="edit-bill" data-id="${b.id}" aria-label="Edit ${esc(b.name)}">${icon('settings',16)}</button><button class="row-action" data-action="delete-bill" data-id="${b.id}" aria-label="Delete ${esc(b.name)}">${icon('x',16)}</button></div></div>`).join('')}</div>`:empty('No bills yet','Add recurring obligations to see them in your weekly and monthly plans.','new-bill','Add bill')}</section>`;}

function goalsPage(){return `${titleRow('SAVINGS','Build toward what matters.','Track contributions and withdrawals without counting them as spending.',button(`${icon('plus',16)} New goal`,'new-goal','primary'))}${state.goals.length?`<div class="goal-grid">${state.goals.map(g=>{const saved=goalSaved(g),pct=g.targetCents?Math.min(100,Math.max(0,saved/g.targetCents*100)):0;const recent=g.movements.filter(m=>m.amountCents>0&&m.date>=addDays(today(),-90)),weekly=recent.length?sum(recent,m=>m.amountCents)/13:0,estimate=weekly>0&&saved<g.targetCents?addDays(today(),Math.ceil((g.targetCents-saved)/weekly*7)):null;return `<section class="panel goal-card"><div class="goal-head"><span class="goal-icon">${icon('target',20)}</span><div><button class="row-action" data-action="edit-goal" data-id="${g.id}" aria-label="Edit ${esc(g.name)}">${icon('settings',16)}</button><button class="row-action" data-action="delete-goal" data-id="${g.id}" aria-label="Delete ${esc(g.name)}">${icon('x',16)}</button></div></div><h2>${esc(g.name)}</h2><div class="goal-numbers"><strong>${fmt(saved)}</strong><span>of ${fmt(g.targetCents)}</span></div><div class="goal-track"><div style="width:${pct}%"></div></div><div class="goal-meta"><span>${Math.round(pct)}% complete</span><span>${fmt(Math.max(0,g.targetCents-saved))} left</span></div><p class="goal-estimate">${g.targetDate?`Target: ${niceDate(g.targetDate)}`:estimate?`Estimated completion: ${niceDate(estimate)}`:'Add contributions to see an estimate'}</p><div class="goal-actions">${button('Contribute','goal-contribute','secondary',`data-id="${g.id}"`)}${button('Withdraw','goal-withdraw','secondary',`data-id="${g.id}"`)}</div></section>`;}).join('')}</div>`:empty('Make room for a goal','Create a savings goal, then record contributions as you go.','new-goal','Create a goal')}`;}

function analyticsPage(){const range=currentRange(),m=metrics(state.transactions,range),expense=m.rows.filter(t=>t.type==='Expense'),income=m.rows.filter(t=>t.type==='Income'),byCategory=Object.entries(groupSum(expense,t=>t.category)).sort((a,b)=>b[1]-a[1]);const days=Math.max(1,Math.round((dateObj(range.to)-dateObj(range.from))/86400000)+1),weeks=days/7,months=days/30.4375;const series=[];let cursor=monthStart(range.from),guard=0;while(cursor<=range.to&&guard++<60){const mr={from:cursor,to:monthEnd(cursor)},mm=metrics(state.transactions,mr);series.push({label:dateObj(cursor).toLocaleDateString(undefined,{month:'short',year:'2-digit'}),income:mm.income,expense:mm.expenses});cursor=addMonths(cursor,1);}return `${titleRow('ANALYTICS','Know your patterns.','Only confirmed transactions appear in these reports.')}${tabPeriod()}<div class="stats-grid four">${card('Average weekly income',fmt(Math.round(m.income/weeks)),'arrow','green')}${card('Average weekly spending',fmt(Math.round(m.expenses/weeks)),'wallet','rose')}${card('Average monthly spending',fmt(Math.round(m.expenses/months)),'calendar','blue')}${card('Savings rate',m.income?`${Math.round(m.savings/m.income*100)}%`:'—','target','violet')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Monthly trends</h2><p>Income versus spending</p></div></div>${series.length?`<div class="trend-chart">${series.map(x=>{const max=Math.max(100,...series.flatMap(v=>[v.income,v.expense]));return `<div class="trend-month"><div class="trend-bars"><div class="trend-income" style="height:${Math.max(2,x.income/max*100)}%" title="${esc(x.label)} income: ${fmt(x.income)}"></div><div class="trend-expense" style="height:${Math.max(2,x.expense/max*100)}%" title="${esc(x.label)} expenses: ${fmt(x.expense)}"></div></div><span>${esc(x.label)}</span></div>`;}).join('')}</div><div class="legend trend-legend"><i class="dot green"></i> Income <i class="dot slate"></i> Expenses</div>`:empty('No trends yet','Add transactions to see monthly patterns.')}</section><section class="panel"><div class="panel-head"><div><h2>Top spending categories</h2><p>Based on paid expenses</p></div></div>${categoryBars(byCategory,m.expenses)}</section></div><section class="panel analytics-bottom"><div class="panel-head"><div><h2>Budget versus actual</h2><p>Weekly allocations during the selected period</p></div></div>${Object.entries(state.allocations).filter(([week])=>inRange(week,range)).length?`<div class="comparison-list">${Object.entries(state.allocations).filter(([week])=>inRange(week,range)).map(([week,alloc])=>{const planned=sum(Object.values(alloc),x=>x),actualSpent=sum(state.transactions.filter(t=>t.type==='Expense'&&actual(t)&&t.date>=week&&t.date<=addDays(week,6)));return `<div class="comparison-row"><strong>${shortDate(week)}</strong><span>Planned ${fmt(planned)}</span><span>Actual ${fmt(actualSpent)}</span><strong class="${planned-actualSpent>=0?'positive':'negative'}">${fmt(planned-actualSpent)} ${planned-actualSpent>=0?'under':'over'}</strong></div>`;}).join('')}</div>`:empty('No budgets in this period','Add weekly category allocations to compare your plan with actual spending.','new-allocation','Plan a week')}</section>`;}

function settingsPage(){return `${titleRow('PREFERENCES','Make it yours.','Your preferences and records are stored in this browser.')}<div class="two-col settings-grid"><section class="panel"><div class="panel-head"><div><h2>Budget preferences</h2><p>These affect display and planning</p></div></div><form id="settings-form" class="form-stack"><label>Currency<select name="currency">${['USD','EUR','GBP','CAD','AUD','JPY'].map(x=>option(x,x,state.settings.currency)).join('')}</select></label><label>Financial week starts<select name="weekStarts">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((x,i)=>option(String(i),x,String(state.settings.weekStarts))).join('')}</select></label><label>Starting cash balance<input name="startingBalance" inputmode="decimal" value="${(state.settings.startingBalanceCents/100).toFixed(2)}"></label><button type="submit" class="btn btn-primary">Save preferences</button></form></section><section class="panel"><div class="panel-head"><div><h2>Categories</h2><p>Available in the transaction ledger</p></div></div><div class="category-chips">${state.categories.map(c=>`<span class="category-chip">${esc(c)}<button data-action="rename-category" data-value="${esc(c)}" aria-label="Rename ${esc(c)}">${icon('settings',13)}</button><button data-action="delete-category" data-value="${esc(c)}" aria-label="Delete ${esc(c)}">${icon('x',13)}</button></span>`).join('')}</div>${button(`${icon('plus',15)} Add category`,'new-category')}</section><section class="panel"><div class="panel-head"><div><h2>Your data</h2><p>Keep a copy outside this browser</p></div></div><p class="muted">Data is saved locally with IndexedDB. It does not sync across devices, and clearing browser storage can erase it. Download backups regularly.</p><div class="button-group">${button(`${icon('download',16)} Download JSON backup`,'backup','primary')}${button(`${icon('upload',16)} Restore backup`,'restore')}</div><div class="divider"></div>${button('Delete all local data','clear-data','danger')}</section><section class="panel"><div class="panel-head"><div><h2>Keyboard shortcuts</h2><p>Move faster through your finances</p></div></div><div class="shortcut-list"><div><span>Quick add</span><kbd>Ctrl J</kbd></div><div><span>Search ledger</span><kbd>Ctrl K</kbd></div><div><span>Undo</span><kbd>Ctrl Z</kbd></div><div><span>Navigate cells</span><kbd>Tab</kbd></div></div></section></div>`;}

function renderModal(){const close=`<button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button>`;return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(modal.title)}"><div class="modal-header"><div><div class="eyebrow">NORTHSTAR</div><h2>${esc(modal.title)}</h2></div>${close}</div>${modalContent()}</div></div>`;}
function modalContent(){const d=modal.data||{};switch(modal.kind){case 'transaction':return `<form id="transaction-form" class="form-stack"><div class="form-row"><label>Date<input type="date" name="date" value="${esc(d.date||today())}" required></label><label>Type<select name="type" id="modal-tx-type">${typeOptions(d.type||'Expense')}</select></label></div><label>Description<input name="description" value="${esc(d.description||'')}" placeholder="What was it for?" required autofocus></label><div class="form-row"><label>Amount<input name="amount" inputmode="decimal" value="${d.amountCents!=null?(d.amountCents/100).toFixed(2):''}" placeholder="0.00" required></label><label>Category<select name="category">${catOptions(d.category||'Other')}</select></label></div><div class="form-row"><label>Status<select name="status" id="modal-tx-status">${statusOptions(d.type||'Expense').map(x=>option(x,x,d.status||statusOptions(d.type||'Expense')[0])).join('')}</select></label><label>Notes<input name="notes" value="${esc(d.notes||'')}" placeholder="Optional"></label></div><div class="modal-actions">${button('Cancel','close-modal')}<button type="submit" class="btn btn-primary">${d.id?'Save changes':'Add transaction'}</button></div></form>`;
 case 'bill':return `<form id="bill-form" class="form-stack"><label>Bill name<input name="name" value="${esc(d.name||'')}" required placeholder="e.g. Internet"></label><div class="form-row"><label>Amount<input name="amount" inputmode="decimal" value="${d.amountCents!=null?(d.amountCents/100).toFixed(2):''}" required placeholder="0.00"></label><label>Category<select name="category">${catOptions(d.category||'Utilities')}</select></label></div><div class="form-row"><label>Frequency<select name="frequency">${FREQUENCIES.map(x=>option(x,x,d.frequency||'Monthly')).join('')}</select></label><label>Next due date<input type="date" name="nextDue" value="${esc(d.nextDue||today())}" required></label></div><label>Notes<input name="notes" value="${esc(d.notes||'')}" placeholder="Optional"></label><div class="modal-actions">${button('Cancel','close-modal')}<button type="submit" class="btn btn-primary">Save bill</button></div></form>`;
 case 'pay':return `<form id="pay-form" class="form-stack"><p class="muted">Record the actual payment. This creates one expense transaction and moves the bill to its next due date.</p><div class="form-row"><label>Payment date<input type="date" name="date" value="${today()}" required></label><label>Actual amount<input name="amount" inputmode="decimal" value="${(d.amountCents/100).toFixed(2)}" required></label></div><div class="modal-actions">${button('Cancel','close-modal')}<button type="submit" class="btn btn-primary">Record payment</button></div></form>`;
 case 'goal':return `<form id="goal-form" class="form-stack"><label>Goal name<input name="name" value="${esc(d.name||'')}" required placeholder="What are you saving for?"></label><div class="form-row"><label>Target amount<input name="target" inputmode="decimal" value="${d.targetCents!=null?(d.targetCents/100).toFixed(2):''}" required placeholder="0.00"></label><label>Target date (optional)<input type="date" name="targetDate" value="${esc(d.targetDate||'')}"></label></div><div class="modal-actions">${button('Cancel','close-modal')}<button type="submit" class="btn btn-primary">Save goal</button></div></form>`;
 case 'movement':return `<form id="movement-form" class="form-stack"><p class="muted">${modal.withdraw?'Withdraw from':'Contribute to'} ${esc(d.name)}. This will also create a cash movement in your ledger.</p><div class="form-row"><label>Date<input type="date" name="date" value="${today()}" required></label><label>Amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label></div><label>Notes<input name="notes" placeholder="Optional"></label><div class="modal-actions">${button('Cancel','close-modal')}<button type="submit" class="btn btn-primary">Record ${modal.withdraw?'withdrawal':'contribution'}</button></div></form>`;
 case 'allocation':return `<form id="allocation-form" class="form-stack"><label>Week beginning<input type="date" name="week" value="${selectedWeek}" required></label><div class="form-row"><label>Category<select name="category">${catOptions('Groceries')}</select></label><label>Planned amount<input name="amount" inputmode="decimal" placeholder="0.00" required></label></div><div class="modal-actions">${button('Cancel','close-modal')}<button type="submit" class="btn btn-primary">Save allocation</button></div></form>`;
 case 'category':return `<form id="category-form" class="form-stack"><label>Category name<input name="name" value="${esc(d.name||'')}" required maxlength="40"></label><div class="modal-actions">${button('Cancel','close-modal')}<button type="submit" class="btn btn-primary">Save category</button></div></form>`;
 case 'confirm':return `<p class="muted">${esc(modal.message)}</p><div class="modal-actions">${button('Cancel','close-modal')}${button(esc(modal.confirmLabel||'Delete'),'confirm','danger')}</div>`;
 case 'import':return `<p class="muted">${modal.rows.length} valid transaction${modal.rows.length===1?'':'s'} ready to import. Existing records will remain.</p><div class="import-preview">${modal.rows.slice(0,8).map(t=>`<div><span>${shortDate(t.date)}</span><strong>${esc(t.description)}</strong><span>${esc(t.type)}</span><strong>${fmt(t.amountCents)}</strong></div>`).join('')}${modal.rows.length>8?`<p>…and ${modal.rows.length-8} more</p>`:''}</div><div class="modal-actions">${button('Cancel','close-modal')}${button(`Import ${modal.rows.length} rows`,'confirm-import','primary')}</div>`;
 default:return '';}}

function openModal(kind,title,data={}){modal={kind,title,data};render();setTimeout(()=>document.querySelector('.modal input[autofocus], .modal input')?.focus(),0);}
function closeModal(){modal=null;render();}
function confirmAction(title,message,yes,confirmLabel='Delete'){modal={kind:'confirm',title,message,yes,confirmLabel};render();}
function addTransaction(data){remember();state.transactions.push({id:uid(),...data});changed('Transaction saved.');}
function editTransaction(id,data){const i=state.transactions.findIndex(t=>t.id===id);if(i<0)return;remember();state.transactions[i]={...state.transactions[i],...data};syncGoalMovement(state.transactions[i]);changed('Transaction updated.');}
function syncGoalMovement(t){if(!t.goalId||!t.movementId)return;const movement=state.goals.find(g=>g.id===t.goalId)?.movements.find(m=>m.id===t.movementId);if(movement){movement.date=t.date;movement.amountCents=t.direction==='in'?-t.amountCents:t.amountCents;movement.notes=t.notes;}}
function removeGoalMovement(t){if(!t.goalId||!t.movementId)return;const goal=state.goals.find(g=>g.id===t.goalId);if(goal)goal.movements=goal.movements.filter(m=>m.id!==t.movementId);}
function validAmount(v,allowZero=false){const n=cents(v);if(n===null||n<0||(!allowZero&&n===0))throw Error('Enter an amount greater than zero with at most two decimals.');return n;}
function formData(form){return Object.fromEntries(new FormData(form));}
function handleSubmit(e){const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const d=formData(form);try{switch(form.id){case 'transaction-form':{const amountCents=validAmount(d.amount),data={date:d.date,description:d.description.trim(),category:d.category,type:d.type,amountCents,status:d.status,notes:d.notes.trim()};if(!data.description)throw Error('Description is required.');if(modal.data.id)editTransaction(modal.data.id,data);else addTransaction(data);modal=null;break;}
 case 'bill-form':{const amountCents=validAmount(d.amount),data={name:d.name.trim(),amountCents,category:d.category,frequency:d.frequency,nextDue:d.nextDue,notes:d.notes.trim()};if(!data.name)throw Error('Bill name is required.');remember();const i=state.bills.findIndex(b=>b.id===modal.data.id);if(i>=0)state.bills[i]={...state.bills[i],...data};else state.bills.push({id:uid(),...data});modal=null;changed('Bill saved.');break;}
 case 'pay-form':{const bill=state.bills.find(b=>b.id===modal.data.id);if(!bill)throw Error('Bill no longer exists.');const amountCents=validAmount(d.amount);remember();state.transactions.push({id:uid(),date:d.date,description:bill.name,category:bill.category,type:'Expense',amountCents,status:'Paid',notes:`Recurring bill · ${bill.frequency}`,billId:bill.id});bill.lastPaidDate=bill.nextDue;bill.nextDue=nextDue(bill.nextDue,bill.frequency);while(bill.nextDue<=d.date)bill.nextDue=nextDue(bill.nextDue,bill.frequency);modal=null;changed('Payment recorded once in your ledger.');break;}
 case 'goal-form':{const targetCents=validAmount(d.target),data={name:d.name.trim(),targetCents,targetDate:d.targetDate};if(!data.name)throw Error('Goal name is required.');remember();const i=state.goals.findIndex(g=>g.id===modal.data.id);if(i>=0)state.goals[i]={...state.goals[i],...data};else state.goals.push({id:uid(),...data,movements:[]});modal=null;changed('Goal saved.');break;}
 case 'movement-form':{const goal=state.goals.find(g=>g.id===modal.data.id);if(!goal)throw Error('Goal no longer exists.');const amountCents=validAmount(d.amount),signed=modal.withdraw?-amountCents:amountCents;if(modal.withdraw&&goalSaved(goal)<amountCents)throw Error('Withdrawal exceeds saved amount.');remember();const movement={id:uid(),date:d.date,amountCents:signed,notes:d.notes.trim()};goal.movements.push(movement);state.transactions.push({id:uid(),date:d.date,description:`${modal.withdraw?'Withdrawal from':'Contribution to'} ${goal.name}`,category:'Savings Transfers',type:'Savings',amountCents,status:'Cleared',notes:d.notes.trim(),goalId:goal.id,movementId:movement.id,direction:modal.withdraw?'in':'out'});modal=null;changed('Savings movement recorded.');break;}
 case 'allocation-form':{const amountCents=validAmount(d.amount,true),week=weekStart(d.week,state.settings.weekStarts);remember();state.allocations[week] ??= {};state.allocations[week][d.category]=amountCents;selectedWeek=week;modal=null;page='weekly';changed('Allocation saved.');break;}
 case 'category-form':{const name=d.name.trim();if(!name)throw Error('Category name is required.');if(state.categories.some(c=>c.toLowerCase()===name.toLowerCase()&&c!==modal.data.name))throw Error('That category already exists.');remember();if(modal.data.name){const old=modal.data.name;state.categories=state.categories.map(c=>c===old?name:c);state.transactions.forEach(t=>{if(t.category===old)t.category=name;});state.bills.forEach(b=>{if(b.category===old)b.category=name;});Object.values(state.allocations).forEach(a=>{if(old in a){a[name]=a[old];delete a[old];}});}else state.categories.push(name);modal=null;changed('Category saved.');break;}
 case 'settings-form':{const balance=cents(d.startingBalance);if(balance===null)throw Error('Starting balance must be a valid amount.');remember();state.settings={currency:d.currency,weekStarts:Number(d.weekStarts),startingBalanceCents:balance};selectedWeek=weekStart(today(),state.settings.weekStarts);changed('Preferences saved.');break;}}
 render();}catch(err){notify(err.message,true);}}

function handleCellChange(el){const row=el.closest('tr[data-id]'),t=state.transactions.find(x=>x.id===row?.dataset.id),key=el.dataset.cell;if(!t||!key)return;let value=el.value;if(key==='amountCents'){const n=cents(value);if(n===null||n<0){notify('Amount must be a positive number with at most two decimals.',true);el.value=txValue(t,key);return;}value=n;}if(key==='description'&&!value.trim()){notify('Description cannot be empty.',true);el.value=t.description;return;}if(key==='date'&&!value){notify('Date is required.',true);el.value=t.date;return;}if(key==='type'&&value!==t.type){remember();if(t.goalId){removeGoalMovement(t);delete t.goalId;delete t.movementId;delete t.direction;}t.type=value;t.status=statusOptions(value)[0];changed('Type updated.');return;}if(t[key]===value)return;remember();t[key]=value;syncGoalMovement(t);persist();notify('Saved.');}
function pasteGrid(e){const target=e.target;if(!target.matches('.cell-input,.cell-select'))return;const raw=e.clipboardData?.getData('text/plain');if(!raw||!raw.includes('\t'))return;e.preventDefault();const row=target.closest('tr[data-id]'),startIndex=filteredTransactions().findIndex(t=>t.id===row?.dataset.id),colIndex=columns.findIndex(([k])=>k===target.dataset.cell),grid=raw.replace(/\r/g,'').trimEnd().split('\n').map(line=>line.split('\t')),list=filteredTransactions();if(startIndex<0||colIndex<0)return;const updates=[];for(let i=0;i<grid.length;i++){const t=list[startIndex+i];if(!t)break;const patch={};for(let j=0;j<grid[i].length;j++){const key=columns[colIndex+j]?.[0];if(!key)break;const v=grid[i][j].trim();if(key==='amountCents'){const n=cents(v);if(n===null||n<0)return notify(`Paste rejected: invalid amount in row ${i+1}.`,true);patch[key]=n;}else if(key==='type'){if(!['Income','Expense','Transfer','Savings'].includes(v))return notify(`Paste rejected: invalid type in row ${i+1}.`,true);patch[key]=v;}else if(key==='date'){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return notify(`Paste rejected: invalid date in row ${i+1}.`,true);patch[key]=v;}else if(key==='description'&&!v)return notify('Paste rejected: blank description.',true);else patch[key]=v;}updates.push([t,patch]);}remember();for(const [t,patch] of updates){Object.assign(t,patch);if(patch.type&&!patch.status)t.status=statusOptions(t.type)[0];}changed(`${updates.length} row${updates.length===1?'':'s'} updated.`);}

function handleClick(e){const pageButton=e.target.closest('[data-page]');if(pageButton){page=pageButton.dataset.page;mobileNav=false;render();window.scrollTo(0,0);return;}const el=e.target.closest('[data-action]');if(!el)return;if(el.classList.contains('modal-backdrop')&&e.target!==el)return;const a=el.dataset.action,id=el.dataset.id,v=el.dataset.value;switch(a){case 'toggle-nav':mobileNav=!mobileNav;render();break;case 'close-modal':closeModal();break;case 'quick-add':case 'new-transaction':openModal('transaction','Add transaction');break;case 'add-on-date':openModal('transaction','Add transaction',{date:selectedDate});break;case 'new-row':addTransaction({date:today(),description:'New entry',category:'Other',type:'Expense',amountCents:0,status:'Upcoming',notes:''});break;case 'duplicate-row':{const t=state.transactions.find(x=>x.id===id);if(t){remember();const copy={...structuredClone(t),id:uid(),description:`${t.description} copy`};delete copy.goalId;delete copy.movementId;delete copy.billId;state.transactions.push(copy);changed('Row duplicated.');}break;}case 'delete-row':confirmAction('Delete transaction','This entry will be removed from your ledger.',()=>{remember();const t=state.transactions.find(t=>t.id===id);if(t)removeGoalMovement(t);state.transactions=state.transactions.filter(t=>t.id!==id);changed('Transaction deleted.');});break;
 case 'sort':if(sortBy===v)sortDir*=-1;else{sortBy=v;sortDir=v==='date'?-1:1;}render();break;case 'undo':undo();break;case 'period':period=v;render();break;case 'prev-period':anchor=period==='week'?addDays(anchor,-7):period==='year'?addMonths(anchor,-12):addMonths(anchor,-1);render();break;case 'next-period':anchor=period==='week'?addDays(anchor,7):period==='year'?addMonths(anchor,12):addMonths(anchor,1);render();break;
 case 'prev-week':selectedWeek=addDays(selectedWeek,-7);render();break;case 'next-week':selectedWeek=addDays(selectedWeek,7);render();break;case 'prev-month':selectedMonth=addMonths(selectedMonth,-1);selectedDate=selectedMonth;render();break;case 'next-month':selectedMonth=addMonths(selectedMonth,1);selectedDate=selectedMonth;render();break;case 'select-date':selectedDate=v;render();break;
 case 'new-bill':openModal('bill','Add recurring bill');break;case 'edit-bill':openModal('bill','Edit recurring bill',state.bills.find(b=>b.id===id));break;case 'delete-bill':confirmAction('Delete bill','The recurring schedule will be removed. Past recorded payments remain in your ledger.',()=>{remember();state.bills=state.bills.filter(b=>b.id!==id);changed('Bill deleted.');});break;case 'pay-bill':openModal('pay','Record bill payment',state.bills.find(b=>b.id===id));break;
 case 'new-goal':openModal('goal','Create savings goal');break;case 'edit-goal':openModal('goal','Edit savings goal',state.goals.find(g=>g.id===id));break;case 'delete-goal':confirmAction('Delete goal','The goal will be removed. Its cash movements remain in your ledger.',()=>{remember();state.goals=state.goals.filter(g=>g.id!==id);changed('Goal deleted.');});break;case 'goal-contribute':case 'goal-withdraw':modal={kind:'movement',title:a==='goal-withdraw'?'Withdraw savings':'Add contribution',data:state.goals.find(g=>g.id===id),withdraw:a==='goal-withdraw'};render();break;
 case 'new-allocation':openModal('allocation','Plan a category');break;case 'delete-allocation':confirmAction('Remove allocation',`Remove the ${v} plan for this week?`,()=>{remember();delete state.allocations[selectedWeek][v];changed('Allocation removed.');});break;
 case 'new-category':openModal('category','Add category');break;case 'rename-category':openModal('category','Rename category',{name:v});break;case 'delete-category':{const used=state.transactions.some(t=>t.category===v)||state.bills.some(b=>b.category===v)||Object.values(state.allocations).some(a=>v in a);if(used)return notify('This category is in use. Rename it instead.',true);confirmAction('Delete category',`Remove ${v} from your categories?`,()=>{remember();state.categories=state.categories.filter(c=>c!==v);changed('Category deleted.');});break;}
 case 'export-csv':download(`northstar-transactions-${today()}.csv`,toCsv(state.transactions),'text/csv');break;case 'import-csv':document.querySelector('#file-import').click();break;case 'backup':download(`northstar-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');break;case 'restore':document.querySelector('#file-restore').click();break;case 'clear-data':confirmAction('Delete all local data','This permanently clears transactions, bills, goals, allocations, and preferences in this browser. Download a backup first if you may need them.',()=>{remember();state=freshState();changed('Local data cleared.');},'Delete everything');break;
 case 'confirm':{const fn=modal?.yes;modal=null;fn?.();break;}case 'confirm-import':remember();state.transactions.push(...modal.rows);modal=null;changed('CSV transactions imported.');break;case 'global-search':page='transactions';render();setTimeout(()=>document.querySelector('#transaction-search')?.focus(),0);break;}}

document.addEventListener('click',handleClick);
document.addEventListener('submit',handleSubmit);
document.addEventListener('paste',pasteGrid);
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-cell]'))handleCellChange(el);if(el.id==='filter-type'){filterType=el.value;render();}if(el.id==='filter-category'){filterCategory=el.value;render();}if(el.id==='filter-status'){filterStatus=el.value;render();}if(el.dataset.custom){custom[el.dataset.custom]=el.value;render();}if(el.id==='modal-tx-type'){const status=document.querySelector('#modal-tx-status');if(status)status.innerHTML=statusOptions(el.value).map((x,i)=>option(x,x,i===0?x:'' )).join('');}});
document.addEventListener('focusout',e=>{if(e.target.matches('.cell-input'))handleCellChange(e.target);});
document.addEventListener('input',e=>{if(e.target.id==='transaction-search'){search=e.target.value;const caret=e.target.selectionStart;render();const input=document.querySelector('#transaction-search');input?.focus();input?.setSelectionRange(caret,caret);}});
document.addEventListener('keydown',e=>{const editable=e.target.matches('input,select,textarea,[contenteditable]');if(e.key==='Escape'&&modal){closeModal();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();page='transactions';render();document.querySelector('#transaction-search')?.focus();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='j'){e.preventDefault();openModal('transaction','Add transaction');}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!editable){e.preventDefault();undo();}if(e.target.matches('[data-cell]')&&['ArrowRight','ArrowLeft','ArrowUp','ArrowDown','Enter'].includes(e.key)){if(e.key.startsWith('Arrow')&&e.target.matches('input')&&e.target.type==='text'&&!e.ctrlKey)return;e.preventDefault();const cells=[...document.querySelectorAll('.ledger tbody [data-cell]')],i=cells.indexOf(e.target),col=columns.length,next=e.key==='ArrowRight'?i+1:e.key==='ArrowLeft'?i-1:e.key==='ArrowUp'?i-col:e.key==='ArrowDown'?i+col:i+1;cells[next]?.focus();cells[next]?.select?.();}});
document.querySelector('#file-import').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const rows=parseCsv(await file.text());if(!rows.length)throw Error('CSV has no transaction rows.');modal={kind:'import',title:'Preview CSV import',rows};render();}catch(err){notify(err.message,true);}});
document.querySelector('#file-restore').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{const restored=validateBackup(JSON.parse(await file.text()));confirmAction('Restore backup','This replaces all current local data in this browser. Download a backup first if you need the current records.',()=>{remember();state=restored;changed('Backup restored.');},'Replace data');}catch(err){notify(err.message,true);}});
try{state=await loadState();}catch(err){notify('Local storage is unavailable. Changes may not persist in this browser.',true);}
selectedWeek=weekStart(today(),state.settings.weekStarts);
render();
